/// <summary>
///    Initializes fields based on the <c>InventTransferParmLine</c> passed as argument.
/// </summary>
/// <param name="_inventTransferParmLine">
///    The <c>InventTransferParmLine</c>.
/// </param>
void initFromInventTransferParmLine(InventTransferParmLine _inventTransferParmLine)
{
    InventTransferLine  locInventTransferLine;

    next initFromInventTransferParmLine(_inventTransferParmLine);

    locInventTransferLine = this.inventTransferLine();

    this.KCS_SOCPickingReleaseIndicator = locInventTransferLine.KCS_SOCPickingReleaseIndicator;
    this.AVAItemSet                     = locInventTransferLine.AVAItemSet;
    this.AVAItemSetExpanded             = locInventTransferLine.AVAItemSetExpanded;
    this.AVAItemSetComponent            = locInventTransferLine.AVAItemSetComponent;
    this.AVAItemSetParent               = locInventTransferLine.AVAItemSetParent;
    this.AVAItemSetCompQtyPerSerie      = locInventTransferLine.AVAItemSetCompQtyPerSerie;
    this.AVAItemSetSerie                = locInventTransferLine.AVAItemSetSerie;
    this.AVAProdSchedDate               = locInventTransferLine.AVAProdSchedDate;
}

/// <summary>
///    AVA <c>displayAVAQtyRemain</c> method.
/// </summary>
