[SysClientCacheDataMethodAttribute(true)]
display InventTransferQtyRemain displayAVAQtyRemain()
{
    InventTransferQtyRemain retVal;   //@SYS7108

    retVal = this.inventTransferLine().QtyRemainShip;

    return retVal;
}

